from typing import Any, Dict

DEFAULTS = {
    "server": {
        "host": "localhost",
        "port": 8080,
        "ssl": {"enabled": False, "cert_path": None}
    },
    "logging": {
        "level": "INFO",
        "file": None,
        "format": "%(asctime)s - %(name)s - %(levelname)s - %(message)s"
    },
    "features": {"enable_metrics": False, "cache_size": 100}
}

def _deep_merge(defaults: Dict[str, Any], override: Dict[str, Any]) -> Dict[str, Any]:
    result = dict(defaults)
    for key, value in override.items():
        if key in result and isinstance(result[key], dict) and isinstance(value, dict):
            result[key] = _deep_merge(result[key], value)
        else:
            result[key] = value
    return result

def parse_config(filepath: str) -> Dict[str, Any]:
    try:
        with open(filepath, 'r') as f:
            data = json.load(f)
    except (json.JSONDecodeError, OSError) as e:
        raise ValueError(f"Failed to read or parse config file {filepath}: {e}")
    if not isinstance(data, dict):
        raise ValueError(f"Config root must be a JSON object, got {type(data).__name__}")
    return _deep_merge(DEFAULTS, data)
"}

