package main

import (
	"fmt"
	"sync"
)

type Pool struct {
	jobs    chan int
	results chan int
	wg      sync.WaitGroup
}

func NewPool(numWorkers int) *Pool {
	p := &Pool{
		jobs:    make(chan int),
		results: make(chan int, 10),
	}
	for i := 0; i < numWorkers; i++ {
		p.wg.Add(1)
		go func() {
			defer p.wg.Done()
			for j := range p.jobs {
				p.results <- j * j
			}
		}()
	}
	return p
}

func (p *Pool) Start(nums []int) {
	go func() {
		for _, n := range nums {
			p.jobs <- n
		}
		close(p.jobs)
	}()
}

func (p *Pool) Stop() {
	p.wg.Wait()
	close(p.results)
}

func (p *Pool) Results() <-chan int {
