```js
async function processBatch(batchId, records) {
  try {
    const validated = await validateRecords(records);
  } catch (err) {
    throw new Error(`VALIDATION_ERROR: ${err.message}`);
  }

  let transformed;
  try {
    transformed = await transformData(batchId, validated);
  } catch (err) {
    throw new Error(`TRANSFORM_ERROR: Batch ${batchId} - ${err.message}`);
