{"file_path": "retry_decorator.py", "content": "import random
import time
from functools import wraps

def retry_with_backoff(retries=4, base_delay=1.0, jitter=0.2):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            delay = base_delay
            last_exception = None
            for attempt in range(retries + 1):
                try:
                    return func(*args, **kwargs)
                except (requests.exceptions.ConnectionError, TimeoutError) as e:
                    last_exception = e
                    if attempt == retries:
                        raise
                    time.sleep(delay * (1 + random.uniform(-jitter, jitter)))
                    delay *= 2
            raise last_exception
        return wrapper
    return decorator
"}

